// @ts-check
import { defineConfig, fontProviders } from 'astro/config';
import starlight from '@astrojs/starlight';

import mermaid from 'astro-mermaid';
import starlightLinksValidator from 'starlight-links-validator';

// Everything under src/content/docs/ except 404.mdx is generated by
// tools/export_public.py from the markdown edition of the audit. Edit the
// generator, not the pages.

// https://astro.build/config
export default defineConfig({
	// Served from a domain of its own, so no `base` path. This is what canonical
	// URLs, the sitemap and Open Graph tags are built against. Moving the site
	// swaps this line (and adds `base` for a path prefix, such as a GitHub Pages
	// project URL); SITE_BASE in tools/export_public.py and site/public/CNAME
	// follow it.
	site: 'https://den-showcase.json64.dev',
	// Weights must cover every weight the stylesheets actually request. Without
	// them only 400 is fetched and the browser synthesises the rest by thickening
	// the 400 glyphs, which reads as blur — most visibly on the sidebar, which
	// renders Victor Mono at 600.
	fonts: [
		{
			provider: fontProviders.google(),
			name: "Victor Mono",
			cssVariable: "--font-victor-mono",
			weights: [400, 600, 700],
			styles: ["normal", "italic"],
		},
		{
			provider: fontProviders.google(),
			name: "JetBrains Mono",
			cssVariable: "--font-jetbrains-mono",
			weights: [400, 600],
			styles: ["normal", "italic"],
		},
	],
	integrations: [
		// Diagrams read the palette directly instead of carrying their own colour
		// scheme. astro-mermaid's autoTheme only ever picks from {light:'default',
		// dark:'dark'} and falls back to the configured base, so a themed base
		// clashes with whatever palette is active ('forest' rendered green on
		// gruvbox brown). Disabling it and styling the 'base' theme through
		// themeCSS means the SVG resolves --sl-color-* at paint time, so diagrams
		// also recolour on a palette switch with no re-render.
		mermaid({
			theme: 'base',
			autoTheme: false,
			mermaidConfig: {
				themeCSS: [
					'.node rect, .node circle, .node ellipse, .node polygon, .node path {',
					'  fill: color-mix(in srgb, var(--sl-color-accent) 12%, var(--sl-color-bg)) !important;',
					'  stroke: color-mix(in srgb, var(--sl-color-accent) 55%, transparent) !important;',
					'}',
					'.node .label, .nodeLabel, .node text { color: var(--sl-color-white) !important; fill: var(--sl-color-white) !important; }',
					'.edgePath .path, .flowchart-link, .messageLine0, .messageLine1 { stroke: var(--sl-color-gray-3) !important; }',
					'.arrowheadPath, marker path, defs marker path { fill: var(--sl-color-gray-3) !important; stroke: none !important; }',
					'.edgeLabel, .edgeLabel p { background: var(--sl-color-bg) !important; color: var(--sl-color-gray-2) !important; fill: var(--sl-color-bg) !important; }',
					'.edgeLabel .label text, .edgeLabel text { fill: var(--sl-color-gray-2) !important; }',
					'.cluster rect { fill: color-mix(in srgb, var(--sl-color-accent) 5%, var(--sl-color-bg)) !important; stroke: var(--sl-color-hairline-light) !important; }',
					'.cluster text, .cluster .label { fill: var(--sl-color-gray-2) !important; color: var(--sl-color-gray-2) !important; }',
				].join('\n'),
			},
		}),
		starlight({
			title: 'den config audit',
			// The 404 page is src/content/docs/404.mdx. Starlight's own /404 route
			// would shadow it and warn on every build.
			disable404Route: true,
			// Every scorecard's evidence block is fenced as `score-evidence`, a label for
			// readers rather than a grammar; render it as plain text without a warning per page.
			expressiveCode: {
				shiki: { langAlias: { 'score-evidence': 'txt' } },
			},
			// A broken cross-reference is the failure this site is most exposed to:
			// it renders as ordinary text, so nothing about the page says the link
			// went nowhere. Fail the build on one instead.
			plugins: [
				starlightLinksValidator({
					errorOnRelativeLinks: false,
					errorOnLocalLinks: false,
				}),
			],
			social: [
				{ icon: 'github', label: 'GitHub', href: 'https://github.com/sini/den-public-audit' }
			],
			// Autogenerated groups follow the export's directory layout, so a config
			// added to or dropped from the audit needs no edit here.
			sidebar: [
				{
					label: 'Overview',
					items: [
						{ label: 'Overview', slug: 'index' },
						{ label: 'Ranking', slug: 'ranking' },
						// One entry, not one per config: 100+ owner/repo entries made the sidebar a wall. The index page
						// groups them by owner, and every config page links back to it.
						{ label: 'Config index', slug: 'configs' },
						{ label: 'Glossary', slug: 'glossary' },
					],
				},
				{
					label: 'Libraries',
					collapsed: true,
					items: [{ autogenerate: { directory: 'libraries', collapsed: true } }],
				},
				{
					label: 'Census',
					items: [
						{ label: 'The census files', slug: 'census' },
						{ label: 'Summary', slug: 'census/summary' },
					],
				},
				{
					label: 'Synthesis',
					items: [{ autogenerate: { directory: 'synthesis' } }],
				},
				{
					label: 'Method',
					items: [{ autogenerate: { directory: 'method' } }],
				},
				{
					label: 'Patterns',
					items: [{ label: 'The sini/nix-config study', slug: 'patterns/sini-nix-config' }],
				},
			],
			components: {
				Head: './src/components/Head.astro',
				Footer: './src/components/Footer.astro',
				ThemeProvider: './src/components/ThemeProvider.astro',
				ThemeSelect: './src/components/ThemeSelect.astro',
			},
			// No editLink: every page is generated, so an edit link would point at a
			// file whose changes the next export overwrites.
			customCss: [
				'./src/styles/layout.css',
				'./src/styles/custom.css'
			],
		}),
	],
});
